import { tr } from './tr.js'
import { fmtMoney, moneyTokens } from './money.js'

// A structured, source-cited course — distinct from the narrative "Истории"
// in lessons.js. Every lesson here traces to a named primary source (a US
// regulator, central bank, or university), and every track ends with a real
// pass/fail exam that gates the next track. This is deliberately NOT framed
// as issuing a real credential (CFA charter, Series 65 license, a
// university degree) — those require paid, proctored, identity-verified
// exams through the actual institutions. What this can honestly claim is:
// the same body of knowledge, explained plainly, checked with a real exam.

function fmt(n) {
  return fmtMoney(n)
}

const LESSON_RULE = { ru: 'Правило: ', en: 'Rule: ', es: 'Regla: ', fr: 'Règle : ' }
const LESSON_ACTION = { ru: 'Действие в приложении: ', en: 'In the app: ', es: 'En la app: ', fr: 'Dans l’app : ' }
const needsOf = (ctx) => Object.values(ctx.settings?.needs_budget || {}).reduce((s, v) => s + (Number(v) || 0), 0)

// Every lesson ends the same way: one rule to remember and one thing to do in
// the app (rules of thumb and a concrete action are what change behavior).
function lessonText(lang, paras, rule, action, mine = '') {
  return moneyTokens([...tr(lang, paras), mine, tr(lang, LESSON_RULE) + tr(lang, rule), tr(lang, LESSON_ACTION) + tr(lang, action)].filter(Boolean).join('\n\n'))
}

